package com.dialectrec;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Bundle;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import android.database.Cursor;
import com.dialectrec.audio.*;
import com.dialectrec.data.*;
import com.dialectrec.importexport.DatasetExporter;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
    public static final String APP_PACKAGE = "com.dialectrec";
    private static final int REQ_AUDIO=20, REQ_IMPORT=21, REQ_EXPORT=22;
    private CorpusDatabase db; private RecorderEngine recorder; private AudioPlayer player; private List<Sentence> task=new ArrayList<>(); private int current=0; private String category=""; private int rangeStart=1, rangeEnd=5000; private boolean pendingRecord=false; private Uri exportUri;
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
    private TextView title(String text){TextView v=new TextView(this);v.setText(text);v.setTextSize(22);v.setTextColor(0xff1f2937);v.setPadding(dp(16),dp(16),dp(16),dp(12));return v;}
    private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setMinHeight(dp(48));return b;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(12),dp(16),dp(24));return l;}
    private ScrollView page(LinearLayout content){ScrollView s=new ScrollView(this);s.addView(content);setContentView(s);return s;}
    @Override public void onCreate(Bundle state){super.onCreate(state);db=new CorpusDatabase(this);player=new AudioPlayer();recorder=new RecorderEngine(message -> runOnUiThread(() -> toast(message)));new Thread(() -> {try{db.seed(this);runOnUiThread(this::route);}catch(Exception e){runOnUiThread(() -> error("句库初始化失败",e));}}).start();}
    private void route(){if(db.getSetting("speaker_id")==null)showOnboarding();else showHome();}
    private void showOnboarding(){LinearLayout l=column();l.addView(title("方言语料采集"));TextView intro=new TextView(this);intro.setText("这是一个离线语音采集工具。你会看到书面汉语提示，请用自己自然的方言表达意思。录音只保存在本机，完成后请及时导出 ZIP。\n\n内置统一句库：5,000 条，支持按主题和句号范围选择任务。");intro.setTextSize(17);intro.setPadding(0,0,0,dp(16));l.addView(intro);EditText id=new EditText(this);id.setHint("研究者分配的发音人 ID（必填）");l.addView(id);EditText dialect=new EditText(this);dialect.setHint("方言名称和方言点（必填）");l.addView(dialect);Button save=button("建立资料并开始");save.setOnClickListener(v->{String a=id.getText().toString().trim(),b=dialect.getText().toString().trim();if(a.isEmpty()||b.isEmpty()){toast("请填写发音人 ID 和方言点");return;}db.saveSpeaker(a,b);showHome();});l.addView(save);Button importBtn=button("导入外部 TXT/CSV 句库");importBtn.setOnClickListener(v->pickImport());l.addView(importBtn);page(l);}
    private void showHome(){LinearLayout l=column();l.addView(title("方言语料采集"));TextView info=new TextView(this);info.setText("发音人："+db.getSetting("speaker_id")+"\n方言点："+db.getSetting("dialect")+"\n句库："+db.getSetting("corpus_id")+" / "+db.getSetting("corpus_version"));info.setTextSize(16);l.addView(info);TextView stats=new TextView(this);stats.setText("总句数："+db.count(null)+"\n已完成："+db.count("completed")+"\n未录制："+db.count("not_recorded")+"\n已跳过："+db.count("skipped"));stats.setTextSize(18);stats.setPadding(0,dp(18),0,dp(18));l.addView(stats);Button go=button("继续录音");go.setOnClickListener(v->showTaskSelection());l.addView(go);Button list=button("全部句子与状态");list.setOnClickListener(v->showList());l.addView(list);Button imp=button("导入 TXT/CSV 句库");imp.setOnClickListener(v->pickImport());l.addView(imp);Button exp=button("导出数据 ZIP");exp.setOnClickListener(v->pickExport());l.addView(exp);Button settings=button("设置与帮助");settings.setOnClickListener(v->showSettings());l.addView(settings);page(l);}
    private void showTaskSelection(){LinearLayout l=column();l.addView(title("选择采集任务"));TextView tip=new TextView(this);tip.setText("总库固定不变。你可以选择一个主题和句号范围；录音仍会保留原始 sentence_id。");tip.setTextSize(16);l.addView(tip);Spinner spinner=new Spinner(this);List<String> cats=new ArrayList<>();cats.add("全部主题");cats.addAll(db.categories());ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cats);spinner.setAdapter(ad);l.addView(spinner);EditText from=new EditText(this);from.setHint("起始句号（默认 1）");from.setInputType(2);l.addView(from);EditText to=new EditText(this);to.setHint("结束句号（默认 5000）");to.setInputType(2);l.addView(to);Button start=button("开始此任务");start.setOnClickListener(v->{category=spinner.getSelectedItemPosition()==0?"":spinner.getSelectedItem().toString();rangeStart=parse(from,1);rangeEnd=parse(to,5000);if(rangeEnd<rangeStart){toast("结束句号必须不小于起始句号");return;}task=db.list(category,rangeStart,rangeEnd);if(task.isEmpty()){toast("没有符合条件的句子");return;}current=0;showRecording();});l.addView(start);Button home=button("返回首页");home.setOnClickListener(v->showHome());l.addView(home);page(l);}
    private int parse(EditText e,int fallback){try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception x){return fallback;}}
    private void showRecording(){if(task.isEmpty()){showTaskSelection();return;}Sentence s=task.get(current);LinearLayout l=column();l.addView(title("录音 · "+(current+1)+" / "+task.size()));TextView id=new TextView(this);id.setText(s.id+"  ·  "+s.category+"  ·  "+s.difficulty);id.setTextSize(15);l.addView(id);TextView prompt=new TextView(this);prompt.setText(s.text);prompt.setTextSize(25);prompt.setTextColor(0xff111827);prompt.setPadding(0,dp(22),0,dp(22));l.addView(prompt);TextView hint=new TextView(this);hint.setText("请用方言自然表达这句话的意思，不需要逐字朗读。spoken_transcript 首版不会自动填写。");hint.setTextSize(15);l.addView(hint);Button start=button("开始录音");Button stop=button("结束并保存");Button play=button("试听当前录音");Button skip=button("跳过此句");Button prev=button("上一句");Button next=button("下一句");l.addView(start);l.addView(stop);l.addView(play);l.addView(skip);LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.addView(prev,new LinearLayout.LayoutParams(0,dp(52),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(52),1));l.addView(nav);TextView state=new TextView(this);state.setText("录音期间请保持此页面打开；保存成功后才会标记完成。");state.setTextSize(14);l.addView(state);stop.setEnabled(false);start.setOnClickListener(v->{if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pendingRecord=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_AUDIO);return;}if(beginRecording(s,start,stop,state)){} });stop.setOnClickListener(v->{try{String rid=UUID.randomUUID().toString();File dir=new File(getFilesDir(),"recordings/"+s.id);dir.mkdirs();File wav=new File(dir,rid+".wav");File out=recorder.stop(wav);long duration=WavInspector.inspect(out).frames*1000L/16000L;db.saveRecording(rid,s.id,"recordings/"+s.id+"/"+rid+".wav",duration,1,recorder.captureRate());state.setText("已保存："+duration+" ms；可以试听或进入下一句。");start.setEnabled(true);stop.setEnabled(false);}catch(Exception e){state.setText("保存失败，旧录音仍保留："+e.getMessage());start.setEnabled(true);stop.setEnabled(false);}});play.setOnClickListener(v->{File f=selectedFile(s.id);if(f==null){toast("当前句子还没有已保存录音");return;}try{player.play(f);}catch(Exception e){toast("试听失败："+e.getMessage());}});skip.setOnClickListener(v->skipDialog(s));prev.setOnClickListener(v->{if(current>0){current--;showRecording();}});next.setOnClickListener(v->{if(current+1<task.size()){current++;showRecording();}else{toast("任务已到最后一句");showHome();}});page(l);}
    private boolean beginRecording(Sentence s,Button start,Button stop,TextView state){File dir=new File(getFilesDir(),"recordings/"+s.id);boolean ok=recorder.start(dir);if(ok){start.setEnabled(false);stop.setEnabled(true);state.setText("正在录音……结束后会校验 WAV 并写入数据库。");}return ok;}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ_AUDIO){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&pendingRecord){pendingRecord=false;showRecording();toast("权限已授予，请再次点击开始录音");}else{pendingRecord=false;new AlertDialog.Builder(this).setTitle("需要麦克风权限").setMessage("只有点击开始录音时才会使用麦克风。请在系统设置中允许后重试。\n\n如果拒绝，句库浏览和导出仍可使用。") .setPositiveButton("知道了",null).show();}}}
    private void skipDialog(Sentence s){String[] reasons={"无法自然表达","不了解含义","暂时跳过","其他"};new AlertDialog.Builder(this).setTitle("选择跳过原因").setItems(reasons,(d,w)->{db.skip(s.id,reasons[w]);if(current+1<task.size()){current++;showRecording();}else showHome();}).setNegativeButton("取消",null).show();}
    private File selectedFile(String sentenceId){try{Cursor c=db.getReadableDatabase().rawQuery("SELECT wav_path FROM recording WHERE sentence_id=? AND selected=1 AND status='completed' ORDER BY take_no DESC LIMIT 1",new String[]{sentenceId});try{if(c.moveToFirst())return new File(getFilesDir(),c.getString(0));}finally{c.close();}}catch(Exception ignored){}return null;}
    private void showList(){LinearLayout l=column();l.addView(title("全部句子"));TextView summary=new TextView(this);summary.setText("共 "+db.count(null)+" 句；已完成 "+db.count("completed")+"；已跳过 "+db.count("skipped"));summary.setTextSize(17);l.addView(summary);List<Sentence> rows=db.list("",1,Math.min(db.count(null),200));for(Sentence s:rows){TextView v=new TextView(this);v.setText(s.id+"  "+s.text);v.setTextSize(15);v.setPadding(0,dp(8),0,dp(8));l.addView(v);}Button back=button("返回首页");back.setOnClickListener(v->showHome());l.addView(back);page(l);}
    private void showSettings(){LinearLayout l=column();l.addView(title("设置与帮助"));TextView t=new TextView(this);t.setText("发音人 ID："+db.getSetting("speaker_id")+"\n方言点："+db.getSetting("dialect")+"\n\n音频目标：PCM WAV / 16 kHz / 16-bit / mono\n录音文件保存在 App 专属目录。导出 ZIP 后不会自动删除源文件。\n\n如果清除 App 数据或卸载，未导出的录音可能丢失，请及时导出。");t.setTextSize(16);l.addView(t);Button back=button("返回首页");back.setOnClickListener(v->showHome());l.addView(back);page(l);}
    private void pickImport(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_IMPORT);}
    private void pickExport(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"dialect_"+db.getSetting("speaker_id")+"_"+System.currentTimeMillis()+".zip");startActivityForResult(i,REQ_EXPORT);}
    @Override protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(code!=RESULT_OK||data==null)return;if(r==REQ_IMPORT){try{String name=data.getData().getLastPathSegment();boolean csv=name!=null&&name.toLowerCase(Locale.ROOT).endsWith("csv");db.importCorpus(getContentResolver().openInputStream(data.getData()),name,csv);toast("句库导入成功；请重新选择任务");}catch(Exception e){error("句库导入失败",e);}}else if(r==REQ_EXPORT){exportUri=data.getData();new Thread(()->{try{DatasetExporter.export(this,db,exportUri);runOnUiThread(()->toast("ZIP 导出成功，源录音已保留"));}catch(Exception e){runOnUiThread(()->error("导出失败",e));}}).start();}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void error(String title,Exception e){new AlertDialog.Builder(this).setTitle(title).setMessage(String.valueOf(e.getMessage())).setPositiveButton("知道了",null).show();}
    @Override protected void onDestroy(){player.stop();if(recorder!=null&&recorder.isRecording())recorder.cancel();db.close();super.onDestroy();}
}
